"""Class 6 Maths Ch 2 - Lines and Angles."""
from g67 import *

SLUG, NAME, CHNO = "Lines_and_Angles", "Lines and Angles", 2
TYPES = ["acute", "right", "obtuse", "straight", "reflex"]
def atype(d):
    return "acute" if d < 90 else "right" if d == 90 else "obtuse" if d < 180 else "straight" if d == 180 else "reflex"
def tyq(d): return tm(f"An angle of ${d}^\\circ$ is called a(n) ___ angle.", atype(d), [t for t in TYPES if t != atype(d)][:3], f"Compare ${d}^\\circ$ with $90^\\circ$ and $180^\\circ$.")
def clk(h, m):
    x = abs(30 * h - Fr(11, 2) * m); x = x % 360
    return min(x, 360 - x)
def cs(x): return str(int(x)) if Fr(x).denominator == 1 else str(float(x))
def dirn(d):
    if d % 90 == 0: return ['North', 'East', 'South', 'West'][(d // 90) % 4]
    return f"between {['North','East','South','West'][d//90%4]} and {['East','South','West','North'][d//90%4]}"
def segs(n): return n * (n - 1) // 2
def hr(h): return f"{h} o'clock"
def tm_(h, m): return f"{h}:{m:02d}"

